define('core/logger/http',['lodash', 'jquery', 'util/url'], function (_, $, urlHelper) {
  'use strict';

  _ = _ && Object.prototype.hasOwnProperty.call(_, 'default') ? _['default'] : _;
  $ = $ && Object.prototype.hasOwnProperty.call($, 'default') ? $['default'] : $;
  urlHelper = urlHelper && Object.prototype.hasOwnProperty.call(urlHelper, 'default') ? urlHelper['default'] : urlHelper;
  var defaultConfig = {
    url: urlHelper.route('log', 'Log', 'tao'),
    level: 'warning',
    delay: 500
  };
  var config = Object.assign({}, defaultConfig);
  var logQueue = [];
  function push(message) {
    logQueue.push(message);
  }
  function flush() {
    var messages = logQueue;
    logQueue = [];
    send(messages);
  }
  function send(messages) {
    $.ajax({
      url: config.url,
      type: 'POST',
      cache: false,
      data: {
        messages: JSON.stringify(messages)
      },
      dataType: 'json',
      global: false,
      error() {
        _.forEach(flush, function (message) {
          push(message);
        });
      }
    });
  }
  var debouncedFlush = _.debounce(flush, defaultConfig.delay);
  var http = {
    setConfig(newConfig) {
      config = _.defaults(newConfig || {}, defaultConfig);
      if (_.isArray(config.url)) {
        config.url = urlHelper.route(...config.url);
      }
      debouncedFlush = _.debounce(flush, config.delay);
    },
    log(message) {
      if (this.checkMinLevel(config.level, message.level)) {
        push(message);
        debouncedFlush();
      }
    }
  };
  return http;
});
